style.css:
@-moz-document domain("youtube.com") {
:root {
  --yt-spec-base-background: #0a0810 !important;
  --yt-spec-raised-background: #100c1c !important;
  --yt-spec-menu-background: #1a1330 !important;
  --yt-spec-inverted-background: #ede8f8 !important;
  --yt-spec-text-primary: #ede8f8 !important;
  --yt-spec-text-secondary: #a799c8 !important;
  --yt-spec-text-disabled: #6a5d8a !important;
  --yt-spec-call-to-action: #b07cff !important;
  --yt-spec-call-to-action-hover: #d4aaff !important;
  --yt-spec-brand-link-color: #b07cff !important;
  --yt-spec-icon-active: #ede8f8 !important;
  --yt-spec-icon-inactive: #a799c8 !important;
  --yt-spec-outline: #2e2050 !important;
  --yt-spec-10-percent-layer: rgba(176, 124, 255, 0.08) !important;
  --yt-spec-badge-chip-background: #1a1330 !important;
}
html, body, ytd-app, #page-manager {
  background: #0a0810 !important;
  color: #ede8f8 !important;
}
body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: url("https://imgur.com/a/oeRdOvA");
  background-size: cover;
  background-position: center top;
  background-repeat: no-repeat;
  opacity: 0.12;
  z-index: 0;
  pointer-events: none;
}
#page-manager {
  position: relative;
  z-index: 1;
}
#masthead, ytd-masthead, #masthead-container {
  background: #100c1c !important;
  border-bottom: 1px solid #2e2050 !important;
  box-shadow: 0 2px 16px rgba(123, 63, 212, 0.18) !important;
}
ytd-masthead #logo svg path + path,
ytd-masthead #logo svg rect,
.ytd-topbar-logo-renderer svg path[fill="#fff"],
.ytd-topbar-logo-renderer svg path[fill="white"],
#logo tp-yt-iron-icon svg path:not(:first-child) {
  fill: #ffffff !important;
}
#search-form, ytd-searchbox, #search-input, input#search {
  background: #1a1330 !important;
  border: 1.5px solid #2e2050 !important;
  color: #ede8f8 !important;
  border-radius: 24px !important;
}
#search-icon-legacy, button#search-icon-legacy {
  background: #231943 !important;
  border: 1.5px solid #2e2050 !important;
  border-left: none !important;
  border-radius: 0 24px 24px 0 !important;
}
#search-icon-legacy:hover {
  background: #4a1e8a !important;
}
#guide-content, ytd-guide-renderer, ytd-mini-guide-renderer, app-drawer {
  background: #100c1c !important;
  border-right: 1px solid #2e2050 !important;
}
ytd-guide-entry-renderer:hover, ytd-mini-guide-entry-renderer:hover {
  background: #1a1330 !important;
  border-radius: 8px !important;
}
ytd-guide-entry-renderer[aria-selected="true"],
ytd-mini-guide-entry-renderer[aria-selected="true"] {
  background: #231943 !important;
  border-radius: 8px !important;
}
ytd-guide-entry-renderer[aria-selected="true"] yt-icon,
ytd-guide-entry-renderer[aria-selected="true"] .title {
  color: #b07cff !important;
}
yt-chip-cloud-chip-renderer, ytd-chip-cloud-chip-renderer {
  background: #1a1330 !important;
  border: 1.5px solid #2e2050 !important;
  color: #a799c8 !important;
  border-radius: 20px !important;
}
yt-chip-cloud-chip-renderer[chip-style="STYLE_DEFAULT_ACTIVE"],
ytd-chip-cloud-chip-renderer[chip-style="STYLE_DEFAULT_ACTIVE"] {
  background: #4a1e8a !important;
  border-color: #7b3fd4 !important;
  color: #ede8f8 !important;
}
ytd-thumbnail {
  border-radius: 10px !important;
  overflow: hidden !important;
}
ytd-thumbnail:hover {
  box-shadow: 0 0 0 2px #7b3fd4 !important;
}
#video-title, .ytd-video-meta-block #metadata-line {
  color: #ede8f8 !important;
}
ytd-channel-name a, #metadata-line span {
  color: #a799c8 !important;
}
ytd-rich-shelf-renderer, ytd-reel-shelf-renderer {
  background: #100c1c !important;
  border-radius: 12px !important;
  border: 1px solid #2e2050 !important;
}
#primary, #secondary, ytd-watch-flexy {
  background: #0a0810 !important;
}
.ytp-play-progress, .ytp-swatch-background-color {
  background: #b07cff !important;
}
.ytp-scrubber-button {
  background: #d4aaff !important;
}
h1.ytd-watch-metadata, #title h1 {
  color: #ede8f8 !important;
}
ytd-toggle-button-renderer, ytd-button-renderer, yt-button-shape {
  background: #1a1330 !important;
  border-radius: 20px !important;
  border: 1px solid #2e2050 !important;
  color: #ede8f8 !important;
}
ytd-toggle-button-renderer:hover, ytd-button-renderer:hover, yt-button-shape:hover {
  background: #231943 !important;
  border-color: #7b3fd4 !important;
}
ytd-toggle-button-renderer[aria-pressed="true"] {
  background: #4a1e8a !important;
  border-color: #b07cff !important;
  color: #d4aaff !important;
}
ytd-subscribe-button-renderer yt-button-shape button,
#subscribe-button yt-button-shape button {
  background: #7b3fd4 !important;
  color: #ede8f8 !important;
  border: none !important;
  border-radius: 20px !important;
}
ytd-text-inline-expander, #description-inner {
  background: #1a1330 !important;
  border-radius: 12px !important;
  padding: 14px !important;
}
ytd-comment-thread-renderer, ytd-comment-renderer {
  background: transparent !important;
  border-bottom: 1px solid #1a1330 !important;
}
ytd-comment-renderer #content-text {
  color: #ede8f8 !important;
}
ytd-comment-renderer #author-text {
  color: #b07cff !important;
}
ytd-commentbox #contenteditable-root {
  border-bottom: 2px solid #7b3fd4 !important;
  color: #ede8f8 !important;
}
tp-yt-paper-dialog, ytd-menu-popup-renderer, tp-yt-paper-listbox {
  background: #1a1330 !important;
  border: 1px solid #2e2050 !important;
  border-radius: 10px !important;
}
ytd-menu-service-item-renderer:hover, tp-yt-paper-item:hover {
  background: #231943 !important;
}
::-webkit-scrollbar {
  width: 6px !important;
  height: 6px !important;
}
::-webkit-scrollbar-track {
  background: #0a0810 !important;
}
::-webkit-scrollbar-thumb {
  background: #4a1e8a !important;
  border-radius: 3px !important;
}
::-webkit-scrollbar-thumb:hover {
  background: #7b3fd4 !important;
}
ytd-notification-renderer {
  background: #1a1330 !important;
  border-bottom: 1px solid #2e2050 !important;
}
yt-icon, yt-icon svg path {
  color: #a799c8 !important;
  fill: currentColor !important;
}
ytd-guide-entry-renderer:hover yt-icon {
  color: #d4aaff !important;
}
}
